* { box-sizing: border-box; }
body { margin: 0; color: #182230; background: #f5f7fa; font: 16px/1.5 system-ui, sans-serif; }
.container { max-width: 760px; margin: 56px auto; padding: 32px; background: white; border: 1px solid #e1e6ed; border-radius: 10px; }
h1 { margin: 0 0 24px; font-size: 2rem; }
label { display: block; margin-bottom: 6px; font-weight: 600; }
.form-row, .project-row { display: flex; align-items: center; gap: 12px; }
input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aab4c0; border-radius: 5px; font: inherit; }
button { padding: 10px 14px; border: 0; border-radius: 5px; background: #245fc5; color: white; font: inherit; cursor: pointer; }
button:hover { background: #174caa; }
.project-row { justify-content: space-between; padding: 14px 0; border-bottom: 1px solid #e1e6ed; }
#projects { margin-top: 20px; }
#alert { color: #b42318; margin-bottom: 0; }
@media (max-width: 600px) { .container { margin: 16px; padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }

